&lt;ul&gt;
&lt;li&gt;&lt;span class=&quot;TextRun SCXW103250455 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW103250455 BCX0&quot;&gt;Process specialist works in a manufacturing setting, which may include long hours on the factory floor, overtime, computer work and meetings. The role may involve occasional nights/weekend work.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP SCXW103250455 BCX0&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
