&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with&amp;nbsp;Capital Equipment&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&amp;nbsp;Industrial&amp;nbsp;Automation,&amp;nbsp;Industrial Robotics,&amp;nbsp;Chemical&amp;nbsp;conversion&amp;nbsp;/&amp;nbsp;electrodeposition / plating&amp;nbsp;/&amp;nbsp;dip&amp;nbsp;coatings,&amp;nbsp;Adhesives / Bonding,&amp;nbsp;Welding Systems,&amp;nbsp;Mahine Tools,&amp;nbsp;Laser powder bed fusion,&amp;nbsp;Additive manufacturing&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience designing&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;:&amp;nbsp;Precision mechanisms,&amp;nbsp;Motion systems,&amp;nbsp;Fluid systems,&amp;nbsp;Thermal systems,&amp;nbsp;Vacuum systems,&amp;nbsp;Structural assemblies,&amp;nbsp;Machine enclosures&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
