&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 3&quot;&gt;Cross-Functional Partnership&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;335559738&amp;quot;:160,&amp;quot;335559739&amp;quot;:80}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt; Serve as a key cost accounting partner to Supply Chain (Planning, Procurement, Warehouse), Production, Program Management, and IT, providing subject-matter&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;expertise&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;First Paragraph&quot;&gt;on inventory, costing, and transaction-related accounting matters&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:180,&amp;quot;335559739&amp;quot;:180}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
