&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience leading electrical infrastructure planning and execution for large-scale manufacturing facilities, factory expansions, or industrial equipment deployments.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
