&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Strong technical knowledge of automotive&amp;nbsp;component&amp;nbsp;design, manufacturing processes, safety and test requirements, and appearance approval procedures.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proficient in Geometric Dimensioning and Tolerancing (GD&amp;amp;T) and datum structures.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:259}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
